function makeEnemy(x,z){const g=new THREE.Group();g.position.set(x,0,z);const body=new THREE.Mesh(boxGeo,enemyMat);body.scale.set(.72,1.15,.62);body.position.y=1.05;body.castShadow=true;g.add(body);const skull=new THREE.Mesh(sphereGeo,enemyMat);skull.scale.set(.39,.42,.4);skull.position.set(0,1.84,.12);g.add(skull);for(let s of [-1,1]){const eye=new THREE.Mesh(sphereGeo,enemyEye);eye.scale.set(.065,.065,.05);eye.position.set(s*.15,1.9,.47);g.add(eye);let arm=new THREE.Mesh(boxGeo,enemyMat);arm.scale.set(.18,.85,.2);arm.position.set(s*.46,1.15,.13);arm.rotation.z=s*.2;g.add(arm);}const aura=new THREE.Mesh(new THREE.CircleGeometry(.65,12),new THREE.MeshBasicMaterial({color:0x33583c,transparent:true,opacity:.27}));aura.rotation.x=-Math.PI/2;aura.position.y=.02;g.add(aura);world.add(g);enemies.push({group:g,hp:3,maxHp:3,alive:true,cool:0,attack:0,phase:rand()*8,target:null,patrol:{x,z},hit:0});}
[[-35,-16],[27,8],[42,-55],[-79,-43],[74,17],[-12,72],[12,-50],[92,42]].forEach(p=>makeEnemy(...p));
const state={health:100,stamina:100,scrap:0,spore:0,medkit:1,signals:0,kills:0,time:0,weather:0,running:false,started:false,won:false,crouch:false};
let saved=null;try{saved=JSON.parse(localStorage.getItem('shadowDistrictSave')||'null')}catch{}
function save(){const data={health:state.health,stamina:state.stamina,scrap:state.scrap,spore:state.spore,medkit:state.medkit,signals:state.signals,kills:state.kills,px:player.position.x,pz:player.position.z,active:state.started};localStorage.setItem('shadowDistrictSave',JSON.stringify(data));}
function loadSave(){if(!saved)return false;Object.assign(state,{health:saved.health??100,stamina:saved.stamina??100,scrap:saved.scrap??0,spore:saved.spore??0,medkit:saved.medkit??1,signals:saved.signals??0,kills:saved.kills??0});if(Number.isFinite(saved.px)){player.position.set(saved.px,0,saved.pz||0)}return true;}
let yaw=0,pitch=-.12,locked=false,paused=true,last=performance.now(),attackCooldown=0,damageFlash=0,weatherTimer=30,nearest=null,joy={x:0,y:0},keys={},mobileRun=false;
const overlay=$('#overlay'),hud=$('#hud'), modal=$('#modal'), prompt=$('#prompt');
function setScreen(id){$$('.screen').forEach(x=>x.classList.toggle('active',x.id===id));overlay.style.display=id?'flex':'none';}
function toast(text){const t=$('#toast');t.textContent=text;t.classList.add('on');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('on'),2200)}
function startGame(continuing=false){if(continuing&&saved)loadSave();else{state.health=100;state.stamina=100;state.scrap=0;state.spore=0;state.medkit=1;state.signals=0;state.kills=0;player.position.set(0,0,9);enemies.forEach(e=>{e.alive=true;e.hp=3;e.group.visible=true});pickups.forEach(p=>{if(p.group)p.group.visible=true;if(p.type==='signal'){p.ref.active=false;p.ref.group.visible=true}})}state.started=true;state.won=false;overlay.style.display='none';hud.style.display='block';$('#mobileControls').style.display=innerWidth<721?'flex':'none';toast('FIELD LINK ESTABLISHED · STAY ALERT');save();}
$('#startBtn').onclick=()=>startGame(false);$('#continueBtn').onclick=()=>{if(saved?.active)startGame(true);else toast('No field record found')};
if(saved?.active)$('#continueBtn').textContent='Continue saved run';else $('#continueBtn').style.opacity='.55';
$('#resumeBtn').onclick=()=>resume();$('#pauseBtn').onclick=()=>pause();$('#saveExitBtn').onclick=()=>{save();state.started=false;hud.style.display='none';setScreen('titleScreen');};$('#restartBtn').onclick=()=>startGame(false);
function pause(){if(!state.started)return;state.running=false;document.exitPointerLock?.();setScreen('pauseScreen');}
function resume(){overlay.style.display='none';if(innerWidth>720)canvas.requestPointerLock?.();}
document.addEventListener('pointerlockchange',()=>{locked=document.pointerLockElement===canvas});
canvas.addEventListener('click',()=>{if(state.started&&!modal.classList.contains('open')){if(innerWidth>720&&!locked)canvas.requestPointerLock?.();else attack();}});
document.addEventListener('mousemove',e=>{if(locked){yaw-=e.movementX*.0022;pitch=Math.max(-.55,Math.min(.38,pitch-e.movementY*.0018));}});
document.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='Escape'){if(modal.classList.contains('open'))closeModal();else if(state.started)pause();}if(e.code==='KeyE')interact();if(e.code==='KeyI')openPanel('inventory');if(e.code==='KeyB')openPanel('craft');if(e.code==='KeyJ')openPanel('journal');if(e.code==='KeyC')state.crouch=!state.crouch;if(e.code==='KeyF')useMedkit();if(e.code==='Space')jump();});document.addEventListener('keyup',e=>keys[e.code]=false);
function jump(){if(state.started&&!player.userData.air){player.userData.vy=6.2;player.userData.air=true;}}
function canStand(x,z){for(const c of colliders)if(Math.abs(x-c.x)<c.w&&Math.abs(z-c.z)<c.d)return false;return true;}
function closestPickup(){let best=null,d=3.15;for(const p of pickups){if(p.group&&!p.group.visible)continue;if(p.type==='signal'&&p.ref.active)continue;let dist=player.position.distanceTo(p.pos);if(dist<d){best=p;d=dist}}return best;}
function interact(){if(!state.started)return;let p=closestPickup();if(!p){const safe=Math.hypot(player.position.x,player.position.z)<11;if(safe){state.health=Math.min(100,state.health+15);state.stamina=100;toast('SAFE ZONE · VITALS RESTORED');}else toast('Nothing within reach');return;}if(p.type==='scrap')state.scrap+=1;else if(p.type==='spore')state.spore+=1;else if(p.type==='medkit')state.medkit+=1;else if(p.type==='signal'){p.ref.active=true;p.ref.group.visible=false;state.signals++;toast(`SIGNAL NODE ${state.signals} / 3 ONLINE`);if(state.signals===3)toast('ALL NODES ONLINE · REACH THE NORTH RELAY');save();updateObjective();return;}p.group.visible=false;toast(`${p.label.toUpperCase()} ACQUIRED`);save();updateUI();}
function useMedkit(){if(state.medkit>0&&state.health<100){state.medkit--;state.health=Math.min(100,state.health+45);toast('MEDKIT USED · +45 VITALS');save();updateUI();}else toast(state.medkit?'VITALS ALREADY FULL':'NO MEDKITS');}
function attack(){if(!state.started||attackCooldown>0)return;attackCooldown=.58;let target=null,best=4.2;const dir=new THREE.Vector3(-Math.sin(yaw),0,-Math.cos(yaw));for(const e of enemies){if(!e.alive)continue;const v=e.group.position.clone().sub(player.position);const d=v.length();v.y=0;if(d<best&&dir.dot(v.normalize())>.32){target=e;best=d;}}if(target){target.hp--;target.hit=.22;target.group.rotation.y+=.08;toast(target.hp<=0?'THREAT ELIMINATED':'HIT · CREATURE WOUNDED');if(target.hp<=0){target.alive=false;target.group.visible=false;state.kills++;if(Math.random()<.48){state.scrap++;toast('THREAT ELIMINATED · SALVAGE +1');}save();updateUI();}}else toast('STRIKE MISSED');}
$('#inventoryBtn').onclick=()=>openPanel('inventory');$('#craftBtn').onclick=()=>openPanel('craft');$('#journalBtn').onclick=()=>openPanel('journal');$('#closeModal').onclick=closeModal;modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});
function openPanel(type){if(!state.started)return;modal.classList.add('open');drawPanel(type);}
function closeModal(){modal.classList.remove('open');}
function drawPanel(type){let title='',eyebrow='',html='';if(type==='inventory'){title='Field inventory';eyebrow='Carried resources';html=`<div class="itemrow"><div><div class="itemname">Salvage metal</div><div class="itemdesc">Useful parts recovered from abandoned infrastructure.</div></div><div class="count">${state.scrap}</div></div><div class="itemrow"><div><div class="itemname">Glow spores</div><div class="itemdesc">Reactive organic material. Useful for medical compounds.</div></div><div class="count">${state.spore}</div></div><div class="itemrow"><div><div class="itemname">Field medkit</div><div class="itemdesc">Restores up to 45 vitality. Press F or use below.</div></div><div class="count">${state.medkit}</div><button class="smallbtn" onclick="window.useKit()" ${state.medkit<1||state.health>=100?'disabled':''}>USE</button></div><div class="panel-note">Weapon: field knife · unlimited strikes<br>Signal nodes online: ${state.signals} / 3 · Threats eliminated: ${state.kills}</div>`;}else if(type==='craft'){title='Field crafting';eyebrow='Improvised recipes';html=`<p class="panel-note">Combine scavenged materials into equipment. Recipes consume materials only when crafted.</p><div class="itemrow"><div><div class="itemname">Field medkit</div><div class="itemdesc">Restores 45 health · Requires 3 salvage + 1 glow spore</div></div><button class="smallbtn" onclick="window.craftKit()" ${state.scrap<3||state.spore<1?'disabled':''}>CRAFT</button></div><div class="itemrow"><div><div class="itemname">Emergency tonic</div><div class="itemdesc">Restores 35 stamina · Requires 2 glow spores</div></div><button class="smallbtn" onclick="window.craftTonic()" ${state.spore<2?'disabled':''}>CRAFT</button></div><div class="panel-note">Current materials: ${state.scrap} salvage · ${state.spore} glow spores</div>`;}else{title='Mission journal';eyebrow='Protocol: homebound';html=`<div class="questrow"><div><div class="itemname">01 / Restore signal nodes</div><div class="itemdesc">Find and activate all three relay nodes across the district.</div><div class="progressline"><i style="width:${state.signals/3*100}%"></i></div></div><div class="count">${state.signals}/3</div></div><div class="questrow"><div><div class="itemname">02 / Reach north extraction</div><div class="itemdesc">When all nodes are online, return to the extraction beacon in the north sector.</div></div><div class="count">${state.signals===3?'READY':'LOCKED'}</div></div><div class="itemrow"><div><div class="itemname">Safe house</div><div class="itemdesc">Return to the lit courtyard at district center to recover a little health and refill stamina.</div></div><div class="count">ACTIVE</div></div><div class="panel-note">Threats are drawn to movement. Sprinting is faster but burns stamina; crouching reduces speed and exposure.</div>`;}$('#modalTitle').textContent=title;$('#modalEyebrow').textContent=eyebrow;$('#modalBody').innerHTML=html;}
window.useKit=()=>{useMedkit();drawPanel('inventory')};window.craftKit=()=>{if(state.scrap>=3&&state.spore>=1){state.scrap-=3;state.spore--;state.medkit++;toast('FIELD MEDKIT CRAFTED');save();updateUI();drawPanel('craft')}};window.craftTonic=()=>{if(state.spore>=2){state.spore-=2;state.stamina=Math.min(100,state.stamina+35);toast('EMERGENCY TONIC USED · +35 STAMINA');save();updateUI();drawPanel('craft')}};

